import React from 'react';
import { debounce } from 'lodash';

const TweetCard = ({ tweet }) => {
  const handleClick = debounce(() => {
    window.open(tweet.profileLink, '_blank');
  }, 300);

  return (
    <div className="bg-white p-4 rounded-lg shadow-md hover:shadow-lg transition">
      <div className="flex items-center mb-2" style={{width: '00px'}}>
        <img
          src={tweet.profile_pic || '/placeholder.jpg'}
          alt={tweet.author_name}
          className="w-10 h-10 rounded-full mr-3"
        />
        <div>
          <p className="font-semibold text-gray-800">{tweet.author_name}</p>
          <a
            href={tweet.profileLink}
            target="_blank"
            rel="noopener noreferrer"
            className="text-blue-500 text-sm hover:underline"
            onClick={handleClick}
          >
            @{tweet.author_name}
          </a>
        </div>
      </div>
      <p className="text-gray-700 mb-2">{tweet.content}</p>
      <div className="flex space-x-4 text-gray-500 text-sm">
        <span>❤️ {tweet.likes}</span>
        <span>💬 {tweet.comments}</span>
      </div>
    </div>
  );
};

export default TweetCard;
